package com.example.hiringsys.entity; import com.example.hiringsys.enums.EstadoGrupo; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="grupo") public class Grupo { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=100) private String nome; @Column(nullable=false,length=100) private String area; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private EstadoGrupo estado; @Column(nullable=false) private Integer disponiveis; @Column(length=100) private String cargo; @Column(name="criado_em",nullable=false,updatable=false) private LocalDateTime criadoEm; @PrePersist void pre(){if(estado==null)estado=EstadoGrupo.RASCUNHO;if(disponiveis==null)disponiveis=0;if(criadoEm==null)criadoEm=LocalDateTime.now();} public Long getId(){return id;} public void setId(Long v){id=v;} public String getNome(){return nome;} public void setNome(String v){nome=v;} public String getArea(){return area;} public void setArea(String v){area=v;} public EstadoGrupo getEstado(){return estado;} public void setEstado(EstadoGrupo v){estado=v;} public Integer getDisponiveis(){return disponiveis;} public void setDisponiveis(Integer v){disponiveis=v;} public String getCargo(){return cargo;} public void setCargo(String v){cargo=v;} public LocalDateTime getCriadoEm(){return criadoEm;} public void setCriadoEm(LocalDateTime v){criadoEm=v;} }
